  return activityTabs(s.cases,caseIndex,'meeting-case','Recado')+`<div class="meeting-layout"><section class="student-message-card"><span class="eyebrow">Private card · student</span><h2>Professor, olhe para o lado.</h2><p>O aluno abre o cartão, memoriza os detalhes e o fecha antes de falar.</p><div class="mission-actions">${reveal(key,'Aluno: abrir cartão')}</div>${answer(key,`<dl><div><dt>Person</dt><dd lang="en">${escape(item.student.person)}</dd></div><div><dt>Place</dt><dd lang="en">${escape(item.student.place)}</dd></div><div><dt>Landmark</dt><dd lang="en">${escape(item.student.landmark)}</dd></div><div><dt>Time</dt><dd lang="en">${escape(item.student.time)}</dd></div><div><dt>Journey</dt><dd lang="en">${escape(item.student.journey)}</dd></div></dl>`)}${routeToolbox(s.support,'Build the message')}</section><section class="teacher-receiver"><span class="eyebrow">Teacher · what did you hear?</span><h2>${cardOpen?'Feche o cartão antes de transmitir.':'Escolha somente depois de ouvir o aluno.'}</h2><div class="meeting-options">${item.options.map((option,index)=>button(`<strong lang="en">${escape(option.title)}</strong><span lang="en">${escape(option.detail)}</span>`,'meeting-choice',`data-choice="${index}" aria-pressed="${choice===index}" ${cardOpen?'disabled':''}`,'decision-option')).join('')}</div>${choice>=0?`<div class="route-feedback ${correct?'is-correct':'is-wrong'}" role="status"><strong>${correct?'Message understood!':'One detail was not clear.'}</strong><span lang="en">${escape(correct?item.model:'Repeat only the place, time or landmark that changed.')}</span></div>`:''}</section></div>`;
