  return `<div class="deadline-banner"><div><span class="eyebrow">Final live call</span><h2 lang="en">${escape(s.situation)}</h2></div><div class="deadline-clock"><strong>${elapsed}</strong><span>/ ${s.deadline} min</span></div></div><div class="timed-route-layout"><figure class="route-map">${cityMapSvg(s,s.map,{startId:s.route.from,destinationId:s.route.to,route:partialRoute,revealRoute:progress>0,travelerPoint,title:s.route.label})}<figcaption>O professor move o viajante somente depois de ouvir uma instrução clara.</figcaption></figure><section class="live-call-console"><div class="teacher-move"><small>Teacher · Traveler</small>${s.teacherLines.map(line=>`<p lang="en">${escape(line)}</p>`).join('')}</div><div class="journey-meter"><span style="width:${progress/s.checkpoints.length*100}%"></span></div><p><strong>${progress} / ${s.checkpoints.length}</strong> movimentos concluídos</p>${complete?`<div class="arrival-success"><strong>${escape(s.outcome)}</strong><span lang="en">${escape(s.model)}</span></div>${button('Refazer chamada','timed-route-reset','','quiet')}`:button('Mover viajante após a instrução','timed-route-step',`data-step="${progress}"`,'small-button')}${routeToolbox(s.support,'Live-call support')}</section></div>`;
